import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

export default function StudentSection() {
  const [students, setStudents] = useState([]);

  useEffect(() => {
    const fetchStudents = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/students');
        const data = await response.json();
        setStudents(data);
      } catch (error) {
        console.error('Error fetching students:', error);
      }
    };
    fetchStudents();
  }, []);
  const [formData, setFormData] = useState({ 
    rollNumber: '',
    name: '', 
    email: '', 
    department: '' 
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch('http://localhost:5000/api/students', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          rollNumber: formData.rollNumber,
          name: formData.name,
          email: formData.email,
          department: formData.department
        }),
      });
      
      if (!response.ok) throw new Error('Failed to add student');
      
      const newStudent = await response.json();
      setStudents([...students, newStudent]);
      setFormData({ rollNumber: '', name: '', email: '', department: '' });
    } catch (error) {
      console.error('Error adding student:', error);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  return (
    <div className="dashboard-container">
      <div className="sidebar">
        <nav>
          <ul>
            <li><Link to="/"><i className="fas fa-home"></i> Dashboard</Link></li>
            <li><Link to="/college-management"><i className="fas fa-university"></i> College Management</Link></li>
            <li><Link to="/students"><i className="fas fa-user-graduate"></i> Student Section</Link></li>
            <li><Link to="/faculty"><i className="fas fa-chalkboard-teacher"></i> Faculty</Link></li>
            <li><Link to="/courses"><i className="fas fa-book"></i> Courses</Link></li>
            <li><Link to="/attendance"><i className="fas fa-clipboard-check"></i> Attendance</Link></li>
            <li><Link to="/grades"><i className="fas fa-graduation-cap"></i> Grades</Link></li>
          </ul>
        </nav>
      </div>
      <div className="main-content">
        <h1 className="text-center mb-4">Student Management</h1>
      
      <div className="card">
        <div className="card-body">
          <form onSubmit={handleSubmit} className="mb-4">
        <div className="form-group mb-3">
          <input
            type="text"
            name="rollNumber"
            className="form-control"
            placeholder="Roll Number"
            value={formData.rollNumber}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group mb-3">
          <input
            type="text"
            name="name"
            className="form-control"
            placeholder="Student Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group mb-3">
          <input
            type="email"
            name="email"
            className="form-control"
            placeholder="Email"
            value={formData.email}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group mb-3">
          <input
            type="text"
            name="department"
            className="form-control"
            placeholder="Department"
            value={formData.department}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit" className="btn btn-success">Add Student</button>
          </form>
          <Link to="/student-search" className="btn btn-primary mt-3">Search Students</Link>
        </div>
      </div>
    </div>
  </div>
  );
}
